  ('cat-fantasy-warriors', 'Fantasy Warriors', 'fantasy-warriors', 'Armored knights, enchanted fighters, and heroic fantasy scenes to color.', 36, 'published'),
  ('cat-vehicles', 'Vehicles', 'vehicles', 'Things that move, ready to color.', 37, 'published');

UPDATE categories SET status = 'published' WHERE id = 'cat-vehicles';

