INSERT OR REPLACE INTO page_categories (page_id, category_id, is_primary)
SELECT id,
  CASE
    WHEN slug IN ('racing-trimaran', 'futuristic-fighter-plane') THEN 'cat-vehicles'
    WHEN slug IN ('fantasy-spear-warrior', 'elf-tech-sword-fighter', 'arcane-mech-warriors', 'spiked-knight-armor') THEN 'cat-fantasy-warriors'
    WHEN slug IN ('shoulder-launcher-soldier', 'tactical-female-scout', 'wasteland-sniper', 'armored-space-squad', 'grenade-lance-scout', 'tech-sniper', 'heavy-gun-motorcycle-rider') THEN 'cat-action-adventure'
    ELSE 'cat-sci-fi-robots'
  END,
  1
FROM coloring_pages
WHERE source_key LIKE 'standard:scifi:%';
